CREATE TABLE IF NOT EXISTS risks (id TEXT PRIMARY KEY,seq INTEGER UNIQUE,incident_date TEXT NOT NULL,incident_time TEXT,reporter TEXT NOT NULL DEFAULT '',unit TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',risk_group TEXT NOT NULL,safety_category TEXT NOT NULL DEFAULT '',risk_code TEXT NOT NULL DEFAULT '',event_title TEXT NOT NULL,event_detail TEXT NOT NULL,immediate_action TEXT NOT NULL DEFAULT '',severity TEXT NOT NULL,is_priority INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'reported',reviewer TEXT NOT NULL DEFAULT '',review_date TEXT,root_cause TEXT NOT NULL DEFAULT '',contributing_factors TEXT NOT NULL DEFAULT '',corrective_action TEXT NOT NULL DEFAULT '',owner TEXT NOT NULL DEFAULT '',due_date TEXT,outcome TEXT NOT NULL DEFAULT '',residual_severity TEXT NOT NULL DEFAULT '',follow_up_date TEXT,lessons_learned TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quality_documents (id TEXT PRIMARY KEY,doc_type TEXT NOT NULL,doc_no TEXT NOT NULL,budget_year INTEGER NOT NULL,month_name TEXT,title TEXT NOT NULL DEFAULT '',form_data TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'draft',author_name TEXT,reviewer_name TEXT,reviewer_note TEXT,reviewed_at TEXT,signed_by TEXT,signed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);